//! 🧪️ Genuine Draw viewports preserve original page margins and independently scaled axes.
use super::*;
#[test]
fn authored_page_canvas_placements_match_neutral_matrices(){let cases:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in cases["cases"].as_array().unwrap(){let content=serde_json::json!({"schema":"drawing.document","id":"page","title":"Page","artboard":row["canvas"],"assets":{},"layers":[]});let document:DrawingSnapshot=serde_json::from_value(content).unwrap();let(mut owner,_)=RetainedCloneSource::admit_owned(document,(),g(grant())).unwrap_or_else(|_|panic!("original page Draw owner"));let read=ChildAdmissionRead{source:semio_framework_io_ports::erase_child_admission_source(owner.borrow(),0x4348494c),admitter:&DRAWING_ADMITTER,vector:&DRAWING_VECTOR_SOURCE};let mut cursor=DrawingPlanCursor::new(DrawingSourceAddress::Page(row["source"]["page"].as_u64().unwrap()as usize),DrawingPlacement::Canvas,target(&row["target"]));let mut fitted=false;for _ in 0..10000{if let DrawingPlanTurn::Fitted{affine,..}=cursor.advance(&read,grant()).unwrap(){near_affine(affine,&row["expectedAffine"]);fitted=true;break}}assert!(fitted);close(&mut cursor);drop(cursor);while !owner.terminal_is_empty(){owner.close_step(g(grant())).unwrap();}}}
